import numpy as np
from scipy.optimize import linprog

def is_feasible(h, n):
    if h.shape != (n,) or not np.all(np.isfinite(h)):
        return False
    if np.any(h < -1e-12) or np.any(h > 1.0 + 1e-12):
        return False
    if abs(np.sum(h) - n / 2.0) > 1e-10 * max(1, n):
        return False
    return True

def project_capped(z, n):
    z = np.clip(z.astype(np.float64), -1e12, 1e12)
    s = n / 2.0
    lo = np.min(z) - 1.0
    hi = np.max(z) + 1.0
    for _ in range(80):
        mid = 0.5 * (lo + hi)
        if np.sum(np.clip(z - mid, 0.0, 1.0)) > s:
            lo = mid
        else:
            hi = mid
    h = np.clip(z - 0.5 * (lo + hi), 0.0, 1.0)
    r = s - np.sum(h)
    for _ in range(n + 2):
        if abs(r) < 1e-14:
            break
        if r > 0:
            idx = np.argmax(1.0 - h)
            h[idx] = min(h[idx] + r, 1.0)
        else:
            idx = np.argmax(h)
            h[idx] = max(h[idx] + r, 0.0)
        r = s - np.sum(h)
    if not np.all(np.isfinite(h)) or np.any(h < -1e-14) or np.any(h > 1.0 + 1e-14):
        return None
    return h

def exact_score(h, n):
    if h.shape != (n,) or not np.all(np.isfinite(h)):
        return float('inf')
    if np.any(h < -1e-12) or np.any(h > 1.0 + 1e-12):
        return float('inf')
    return float(np.max(np.correlate(h, 1.0 - h, mode='full') * (2.0 / n)))

def lag_model(x, n):
    L = 2 * n - 1
    q = np.correlate(x, 1.0 - x, mode='full')
    dx = 2.0 / n
    c = dx * q
    G = np.zeros((L, n))
    for d in range(-(n - 1), n):
        row = d + n - 1
        i0 = max(d, 0)
        j0 = max(-d, 0)
        m = n - abs(d)
        G[row, i0:i0 + m] += (1.0 - x[j0:j0 + m])
        G[row, j0:j0 + m] -= x[i0:i0 + m]
    G *= dx
    if not np.all(np.isfinite(c)) or not np.all(np.isfinite(G)):
        return None, None
    return c, G

def lp_step(x, R, c, G, n):
    L = 2 * n - 1
    nv = 2 * n + 1
    nrows = L + 3 * n + 1
    A_ub = np.zeros((nrows, nv))
    b_ub = np.zeros(nrows)
    A_ub[:L, :n] = G
    A_ub[:L, -1] = -1.0
    b_ub[:L] = G @ x - c
    r = L
    I = np.eye(n)
    A_ub[r:r + n, :n] = I
    A_ub[r:r + n, n:2 * n] = -I
    b_ub[r:r + n] = x
    r += n
    A_ub[r:r + n, :n] = -I
    A_ub[r:r + n, n:2 * n] = -I
    b_ub[r:r + n] = -x
    r += n
    A_ub[r, n:2 * n] = 1.0
    b_ub[r] = R
    A_eq = np.zeros((1, nv))
    A_eq[0, :n] = 1.0
    b_eq = np.array([n / 2.0])
    c_obj = np.zeros(nv)
    c_obj[-1] = 1.0
    bounds = [(0, 1)] * n + [(0, 1)] * n + [(None, None)]
    try:
        res = linprog(c_obj, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                      bounds=bounds, method='highs',
                      options={'maxiter': 500, 'presolve': True})
    except Exception:
        return None
    if not res.success or res.x is None or res.x.shape != (nv,):
        return None
    y = res.x[:n]
    return y if np.all(np.isfinite(y)) else None

def optimize_start(x, n, n_iter):
    x = x.copy().astype(np.float64)
    score = exact_score(x, n)
    R = max(0.1, min(1.5, 0.02 * n))
    Rmax = max(R, min(8.0, 0.10 * n))
    rejs = 0
    for _ in range(n_iter):
        if rejs >= 5 or R < 1e-6:
            break
        c, G = lag_model(x, n)
        if G is None:
            break
        y = lp_step(x, R, c, G, n)
        if y is None:
            R *= 0.25
            rejs += 1
            continue
        y = project_capped(y, n)
        if y is None or not is_feasible(y, n):
            R *= 0.25
            rejs += 1
            continue
        a = np.sum(np.abs(y - x))
        if a > R:
            y = x + (R / a) * 0.999999999999 * (y - x)
            y = project_capped(y, n)
            if y is None or not is_feasible(y, n):
                R *= 0.25
                rejs += 1
                continue
        if np.max(np.abs(y - x)) <= 1e-10:
            break
        pred = score - np.max(c + G @ (y - x))
        if pred <= 1e-12:
            break
        best_z, best_s, best_alpha = None, score, -1
        for k in range(9):
            alpha = 1.0 / (2 ** k)
            z = project_capped(x + alpha * (y - x), n)
            if z is None or not is_feasible(z, n):
                continue
            sz = exact_score(z, n)
            if sz < best_s:
                best_s, best_z, best_alpha = sz, z, alpha
        if best_z is None or best_s >= score - 1e-12:
            R *= 0.25
            rejs += 1
            continue
        actual = score - best_s
        rho = actual / pred if pred > 1e-12 else 0.0
        x, score = best_z.copy(), best_s
        rejs = 0
        disp = np.sum(np.abs(x - best_z + best_z - x))  # placeholder
        if rho < 0.1:
            R *= 0.5
        elif rho >= 0.75 and best_alpha == 1.0 and np.sum(np.abs(best_z - y)) < 1e-10 and a >= 0.8 * R:
            R = min(2.0 * R, Rmax)
        R = max(R, 1e-6)
        R = min(R, Rmax)
    return x, score

def build_starts(base, n, rng, count):
    pool = []
    def add(v):
        if v is None:
            return
        for s in pool:
            if np.max(np.abs(v - s)) < 1e-10:
                return
        pool.append(v)
    add(base.copy())
    add(project_capped(base[::-1], n))
    add(project_capped(1.0 - base[::-1], n))
    add(np.full(n, 0.5))
    blk = np.zeros(n)
    blk[:n // 2] = 1.0
    if n % 2:
        blk[n // 2] = 0.5
    add(project_capped(blk, n))
    alt = np.where(np.arange(n) % 2 == 0, 1.0, 0.0).astype(np.float64)
    add(project_capped(alt, n))
    for sd in (0.04, 0.12, 0.30):
        add(project_capped(base + rng.normal(0, sd, n), n))
    add(project_capped(rng.uniform(0, 1, n), n))
    return pool[:count]

